export interface RepoStatus {
    "current": string;
    "tracking": string | null;
    "ahead": number;
    "behind": number;
    "staged": FileEntry[] | null;
    "unstaged": FileEntry[] | null;
    "conflicted": FileEntry[] | null;
}

